// Helper function to compute the sum of the digits of N
function DigitSum(N: int): int
    requires 0 <= N <= 10000
    ensures 0 <= DigitSum(N) <= 40  // since the maximum digit sum for numbers up to 10000 is 40
{
    var sum := 0;
    var current := N;
    while current > 0
        decreases current
    {
        sum := sum + (current % 10);
        current := current / 10;
    }
    return sum;
}

// Helper function to convert an integer to a binary string
function ToBinary(x: int): string
    requires x >= 0
{
    if x == 0 then
        return "0";
    var result := "";
    var current := x;
    while current > 0
        decreases current
    {
        result := (if current % 2 == 0 then "0" else "1") + result;
        current := current / 2;
    }
    return result;
}
